// Ported by hand from game.exe (CEffectPrim process 0xae2660 / render 0xaf88d0); not generated by the RE port workspace.
namespace Ragnarok.Effects.Classic
{
    public readonly partial struct Prim
    {
        // ================================================================ type 0x20 (spirit spheres / coins, EF 228 / 504 / 629)

        /// <summary>Type 0x20: fn_ae2660 — always returns 1 → alive while the age allows.</summary>
        [FxPrimProcess(0x20)]
        public FxCaseResult Case20_E10(FxRuntime rt) => Process_ae2660(rt) ? FxCaseResult.Continue : FxCaseResult.Dead;

        [FxPrimRender(0x20)]
        public void Render20_E10(FxRuntime rt, uint viewMatrix) => Render_af88d0(rt, viewMatrix);

        /// <summary>
        /// CEffectPrim::fn_ae2660 (0xae2660) — camera angles, follow the master; slot 0 live (+0x3e8 == 1): age +0x3f4 +1
        /// (alpha +0x3ea +1 while the age ≤ 200); three wandering angles (+0x3fc/+0x404/+0x40c) step by 1 towards their
        /// targets as in fn_b0f390. The orbit angle +0x414 advances by 1 every tick for kind +0x450 = 0 or ≥ 0x14, every
        /// even age for kinds 1..9; kinds 10..19 step it every (kind − 9) ages by the owner type +0x13c (0: by 1, size 6,
        /// height −15; 1: by 15 while the height sinks by 0.1 to −30 and the size grows by 0.02 to 10). Centre
        /// +0x46c/+0x470/+0x474 = the wander sines (·0.7 when +0x424 == 1, ·0.5 for kinds 1..0x13) plus an orbit circle
        /// of radius 5.5 (+0x424 == 1) or 7, height +0x418; spin +0x41c += 5 + rand() % 5 (wrap at 360). Returns 1.
        /// </summary>
        public bool Process_ae2660(FxRuntime rt)
        {
            CameraAngles_P1(rt);
            FollowMaster_P1();
            if (M.U8(A + 0x3e8) != 1) return true;
            int age = M.I32(A + 0x3f4) + 1;
            M.I32(A + 0x3f4, age);
            if (age <= 0xc8) M.U16(A + 0x3ea, (ushort)(M.U16(A + 0x3ea) + 1));
            for (int k = 0; k < 3; k++)
            {
                uint s = A + 0x3fc + (uint)k * 8;
                float target = M.F32(s + 4), cur = M.F32(s);
                if (target > cur)
                {
                    cur = cur + 1.0f;
                    if (cur > 359.0f) cur = 359.0f;
                    M.F32(s, cur);
                    if (cur > target)
                    {
                        int n = FxOps.Cvtt(cur);
                        int v = 0;
                        if (n != 0)
                        {
                            int r = rt.Rand.Next() % n;
                            v = r < 0 ? 0 : r;
                        }
                        M.F32(s + 4, (float)v);
                    }
                }
                else
                {
                    cur = cur - 1.0f;
                    if (0f > cur) cur = 0f;
                    M.F32(s, cur);
                    if (!(target < cur || float.IsNaN(target) || float.IsNaN(cur)))   // COMISS target, cur; JB
                    {
                        int n = FxOps.Cvtt(cur);
                        int v = 0;
                        if (n != 0)
                        {
                            int r = rt.Rand.Next() % n;
                            v = r < 0 ? 0 : r;
                        }
                        M.F32(s + 4, (float)(0x167 - v));
                    }
                }
            }

            sbyte kind = M.I8(A + 0x450);
            if (kind == 0 || kind >= 0x14)
            {
                StepOrbit_ae2660(1.0f);
            }
            else if (kind < 0xa)
            {
                if ((M.U8(A + 0x3f4) & 1) == 0) StepOrbit_ae2660(1.0f);
            }
            else
            {
                int ownerType = M.I32(A + 0x13c);
                if (ownerType == 0)
                {
                    if (age % (kind - 9) == 0) StepOrbit_ae2660(1.0f);
                    M.F32(A + 0x468, 6.0f);
                    M.F32(A + 0x418, -15.0f);
                }
                else if (ownerType == 1)
                {
                    if (age % (kind - 9) == 0) StepOrbit_ae2660(15.0f);
                    float h = M.F32(A + 0x418) - 0.1f;
                    M.F32(A + 0x418, h);
                    if (!(-30.0f < h)) M.F32(A + 0x418, -30.0f);   // COMISS -30, h; JB
                    float size = M.F32(A + 0x468) + 0.02f;
                    M.F32(A + 0x468, size);
                    if (!(size < 10.0f)) M.F32(A + 0x468, 10.0f);
                }
            }

            float wander, radius;
            if (M.F32(A + 0x424) == 1.0f)
            {
                wander = 0.7f;
                radius = 5.5f;
            }
            else if (kind != 0 && kind < 0x14)
            {
                wander = 0.5f;
                radius = 7.0f;
            }
            else
            {
                wander = 1.0f;
                radius = 7.0f;
            }

            float sx = SinAt(FxOps.Cvtt(M.F32(A + 0x3fc))) * wander;
            float sz = SinAt(FxOps.Cvtt(M.F32(A + 0x404))) * wander;
            float sy = SinAt(FxOps.Cvtt(M.F32(A + 0x40c))) * wander;
            M.F32(A + 0x470, sy);
            int orbit = FxOps.Cvtt(M.F32(A + 0x414));
            M.F32(A + 0x46c, (SinAt(orbit) * radius) + sx);
            M.F32(A + 0x474, (CosAt(orbit) * radius) + sz);
            M.F32(A + 0x470, M.F32(A + 0x418) + M.F32(A + 0x470));
            int rs = rt.Rand.Next() % 5;
            float spin = (float)((rs < 0 ? 0 : rs) + 5) + M.F32(A + 0x41c);
            M.F32(A + 0x41c, spin);
            if (!(spin < 360.0f || float.IsNaN(spin))) M.F32(A + 0x41c, spin - 360.0f);
            return true;
        }

        void StepOrbit_ae2660(float step)
        {
            float o = M.F32(A + 0x414) + step;
            M.F32(A + 0x414, o);
            if (!(o < 360.0f || float.IsNaN(o))) M.F32(A + 0x414, o - 360.0f);
        }

        /// <summary>
        /// CEffectPrim::fn_af88d0 (0xaf88d0) — slot 0 live with alpha &gt; 0: camera-facing squares (corners at
        /// 0/90/180/270°, rotated by FUN_00b0d9c0) at the centre +0x46c.., texture 0. Kind 0x15 first adds a halo of
        /// R = f_468·sin[+0x41c]·0.05 + f_468·3 at half alpha and one of f_468·1.7, kind 0x14 one of f_468·1.3, all blue
        /// (0, 0, 0xff). Then the glow R = f_468·sin·0.05 + f_468 and the core R = f_468·sin·0.05 + f_468·0.5, coloured
        /// by the kind: 0 → (0, 0, 0xff) / (0xff, 0xff, 0); 1 → (0x44, 0x2a, 0x1e) / white; 0x14 → (0x28, 0x28, 0xff) /
        /// (0x96, 0x96, 0xff); 0x15 → (0x28, 0x28, 0xff) / (0xfa, 0xfa, 0xff); 10..13 the element tints.
        /// </summary>
        public void Render_af88d0(FxRuntime rt, uint matrix)
        {
            int count = 0;
            if (M.U8(A + 0x3e8) != 1 || M.I16(A + 0x3ea) <= 0) return;
            System.Span<float> p = stackalloc float[12];
            sbyte kind = M.I8(A + 0x450);
            short alpha = M.I16(A + 0x3ea);
            float size = M.F32(A + 0x468);
            if (kind == 0x15)
            {
                ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 3.0f, (short)(alpha / 2), 0, 0, 0, 0xff);
                ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 1.7f, alpha, 0, 0, 0, 0xff);
            }
            else if (kind == 0x14)
            {
                ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 1.3f, alpha, 0, 0, 0, 0xff);
            }

            // the glow: blend 10 (0 for owner type 1) only for the element kinds 10..13
            short elementBlend = (short)(M.I32(A + 0x13c) == 1 ? 0 : 10);
            switch (kind)
            {
                case 1: ChookgiQuad_af88d0(rt, ref count, p, matrix, size, alpha, 0, 0x44, 0x2a, 0x1e); break;
                case 0xa: ChookgiQuad_af88d0(rt, ref count, p, matrix, size, alpha, elementBlend, 0xff, 0x32, 0x32); break;
                case 0xb: ChookgiQuad_af88d0(rt, ref count, p, matrix, size, alpha, elementBlend, 0xc8, 0xc8, 0x32); break;
                case 0xc: ChookgiQuad_af88d0(rt, ref count, p, matrix, size, alpha, elementBlend, 0x32, 0x32, 0xff); break;
                case 0xd: ChookgiQuad_af88d0(rt, ref count, p, matrix, size, alpha, elementBlend, 0xff, 0xff, 0xff); break;
                case 0x14: case 0x15: ChookgiQuad_af88d0(rt, ref count, p, matrix, size, alpha, 0, 0x28, 0x28, 0xff); break;
                default: ChookgiQuad_af88d0(rt, ref count, p, matrix, size, alpha, 0, 0, 0, 0xff); break;
            }

            switch (kind)
            {
                case 1: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0xff, 0xff, 0xff); break;
                case 0xa: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0xff, 0x32, 0x32); break;
                case 0xb: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0xc8, 0xc8, 0x32); break;
                case 0xc: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0x32, 0x32, 0xff); break;
                case 0xd: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0x64, 0x96, 0x64); break;
                case 0x14: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0x96, 0x96, 0xff); break;
                case 0x15: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0xfa, 0xfa, 0xff); break;
                default: ChookgiQuad_af88d0(rt, ref count, p, matrix, size * 0.5f, alpha, 0, 0xff, 0xff, 0); break;
            }
        }

        /// <summary>One square of fn_af88d0: R = f_468·sin[+0x41c]·0.05 + <paramref name="baseRadius"/>.</summary>
        void ChookgiQuad_af88d0(FxRuntime rt, ref int count, System.Span<float> p, uint matrix, float baseRadius, short alpha,
            short blend, byte r, byte g, byte b)
        {
            int t = FxOps.Cvtt(M.F32(A + 0x41c));
            float size = M.F32(A + 0x468);
            float R = ((size * SinAt(t)) * 0.05f) + baseRadius;
            p.Clear();
            p[0] = R * CosAt(0); p[2] = R * SinAt(0);
            p[3] = R * CosAt(90); p[5] = R * SinAt(90);
            p[6] = R * CosAt(180); p[8] = R * SinAt(180);
            p[9] = R * CosAt(270); p[11] = R * SinAt(270);
            Rotate4_b0d9c0(p, M.I16(A + 0x3ec), M.I16(A + 0x4a0));
            float cx = M.F32(A + 0x46c), cy = M.F32(A + 0x470), cz = M.F32(A + 0x474);
            for (int k = 0; k < 4; k++)
            {
                p[k * 3] = cx + p[k * 3];
                p[k * 3 + 1] = cy + p[k * 3 + 1];
                p[k * 3 + 2] = cz + p[k * 3 + 2];
            }

            Quad_b0a900(rt, ref count, alpha, p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7], p[8], p[9], p[10], p[11],
                matrix, blend, 0, 0, r, g, b, 0f, 1.0f, 0f, 1.0f, 0);
        }
    }
}
